class BenefitReservationStatus(str, Enum):
    ACTIVE = "ACTIVE"
    RELEASED = "RELEASED"
    EXPIRED = "EXPIRED"
    CONSUMED = "CONSUMED"


@dataclass(frozen=True)
class BenefitReservation:
    reservation_id: str
    idempotency_key: str
    policy_id: str
    policy_version: str
    contract_id: str
    unit_id: str
    source_system: str
    source_transaction_id: str
    amount: float
    currency: str
    expires_at_epoch: int
    status: BenefitReservationStatus = BenefitReservationStatus.ACTIVE


@dataclass(frozen=True)
class BenefitReservationCapacity:
    monetary_cap: float
    confirmed_net_amount: float
    active_reserved_amount: float


def validate_benefit_reservation(reservation: BenefitReservation, *, now_epoch: int) -> None:
    required = {
        "reservation_id": reservation.reservation_id,
        "idempotency_key": reservation.idempotency_key,
        "policy_id": reservation.policy_id,
        "policy_version": reservation.policy_version,
        "contract_id": reservation.contract_id,
        "unit_id": reservation.unit_id,
        "source_system": reservation.source_system,
        "source_transaction_id": reservation.source_transaction_id,
        "currency": reservation.currency,
    }
    for field_name, value in required.items():
        if not str(value or "").strip():
            raise ValueError(f"BenefitReservation requiere {field_name}")
    if reservation.amount <= 0:
        raise ValueError("La reserva debe ser mayor que cero")
    if reservation.expires_at_epoch <= 0:
        raise ValueError("La reserva requiere expiracion valida")
    if reservation.status == BenefitReservationStatus.ACTIVE and reservation.expires_at_epoch <= now_epoch:
        raise ValueError("Una reserva ACTIVE no puede estar expirada")


def benefit_reservation_available_amount(capacity: BenefitReservationCapacity) -> float:
    if capacity.monetary_cap < 0 or capacity.confirmed_net_amount < 0 or capacity.active_reserved_amount < 0:
        raise ValueError("Los montos de capacidad no pueden ser negativos")
    return round(max(0.0, capacity.monetary_cap - capacity.confirmed_net_amount - capacity.active_reserved_amount), 2)


def can_reserve_benefit_amount(*, requested_amount: float, capacity: BenefitReservationCapacity) -> bool:
    if requested_amount <= 0:
        raise ValueError("requested_amount debe ser mayor que cero")
    return requested_amount <= benefit_reservation_available_amount(capacity)


def active_reservation_amount(reservations: tuple[BenefitReservation, ...], *, now_epoch: int) -> float:
    return round(sum(
        reservation.amount
        for reservation in reservations
        if reservation.status == BenefitReservationStatus.ACTIVE and reservation.expires_at_epoch > now_epoch
    ), 2)


def reservation_has_economic_effect(reservation: BenefitReservation) -> bool:
    return reservation.status == BenefitReservationStatus.CONSUMED


def reservation_can_transition(current: BenefitReservationStatus, target: BenefitReservationStatus) -> bool:
    allowed = {
        BenefitReservationStatus.ACTIVE: {
            BenefitReservationStatus.RELEASED,
            BenefitReservationStatus.EXPIRED,
            BenefitReservationStatus.CONSUMED,
        },
        BenefitReservationStatus.RELEASED: set(),
        BenefitReservationStatus.EXPIRED: set(),
        BenefitReservationStatus.CONSUMED: set(),
    }
    return target in allowed[current]
